using BenchmarkDotNet.Attributes;
using BenchmarkDotNet.Running;
using BenchmarkDotNet.Jobs;
using TextAnalysis;

[SimpleJob(RuntimeMoniker.Net90)]
[SimpleJob(RuntimeMoniker.Net100)]
[MemoryDiagnoser]
public class TextAnalyzerBenchmarks
{
    private TextAnalyzer _analyzer = null!;

    [GlobalSetup]
    public void Setup()
    {
        // Generate a realistic text with ~1000 words
        var words = new string[]
        {
            "the", "quick", "brown", "fox", "jumps", "over", "lazy", "dog",
            "performance", "benchmarking", "is", "important", "for", "understanding",
            "how", "code", "behaves", "under", "different", "conditions", "and",
            "runtime", "versions", "can", "significantly", "impact", "execution", "speed"
        };
        var rng = new Random(42);
        var parts = new string[1000];
        for (int i = 0; i < parts.Length; i++)
            parts[i] = words[rng.Next(words.Length)];
        string text = string.Join(" ", parts);
        _analyzer = new TextAnalyzer(text);
    }

    [Benchmark]
    public double AverageWordLength() => _analyzer.AverageWordLength();

    [Benchmark]
    public object WordLengthHistogram() => _analyzer.WordLengthHistogram();

    [Benchmark]
    public int UniqueWordCount() => _analyzer.UniqueWordCount();
}

public class Program
{
    public static void Main(string[] args)
    {
        BenchmarkRunner.Run<TextAnalyzerBenchmarks>(args: args);
    }
}

